public class Main {
    public static void main(String[] args) {
        System.out.println(primeFib(10));
    }

    public static double primeFib(int n) {
        List<Double> f = new ArrayList<>(Arrays.asList(0.0, 1.0));
        while (true) {
            f.add(f.get(f.size() - 1) + f.get(f.size() - 2));
            if (isPrime(f.get(f.size() - 1))) {
                n -= 1;
            }
            if (n == 0) {
                return f.get(f.size() - 1);
            }
        }
    }

    public static boolean isPrime(double p) {
        if (p < 2) {
            return false;
        }
        for (int k = 2; k <= Math.min(Math.sqrt(p), p - 1); k++) {
            if (p % k == 0) {
                return false;
            }
        }
        return true;
    }
}

