public class Main {
    public static void main(String[] args) {
        System.out.println(solve(123456));
    }

    public static String solve(int N) {
        List<Integer> digits = new ArrayList<>();
        while (N > 0) {
            digits.add(N % 10);
            N /= 10;
        }

        int sum = 0;
        for (int digit : digits) {
            sum += digit;
        }

        return Integer.toBinaryString(sum);
    }
