public class Main {
    public static boolean moveOneBall(List<Integer> arr) {
        if (arr.size() == 0) {
            return true;
        }
        List<Integer> sortedArray = new ArrayList<>(arr);
        Collections.sort(sortedArray);
        List<Integer> myArr = new ArrayList<>();

        int minValue = Collections.min(arr);
        int minIndex = arr.indexOf(minValue);
        myArr.addAll(arr.subList(minIndex, arr.size()));
        myArr.addAll(arr.subList(0, minIndex));
        for (int i = 0; i < arr.size(); i++) {
            if (!myArr.get(i).equals(sortedArray.get(i))) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        List<Integer> arr = Arrays.asList(4, 2, 3, 1);
        System.out.println(moveOneBall(arr));
    }
