        Map<Object, Object> result = reverseDelete("hello", "eo");
        System.out.println(result.get("s"));
        System.out.println(result.get("isReversed"));
    }

    public static Map<Object, Object> reverseDelete(String s, String c) {
        List<Character> charList = new ArrayList<>();
        for (char ch : s.toCharArray()) {
            if (!c.contains(String.valueOf(ch))) {
                charList.add(ch);
            }
        }
        String newString = String.valueOf(charList);
        boolean isReversed = newString.equals(new StringBuilder(newString).reverse().toString());
        Map<Object, Object> result = new HashMap<>();
        result.put("s", newString);
        result.put("isReversed", isReversed);
        return result;
    }
}

